using UnityEngine;
public sealed class SummitDotVisual : MonoBehaviour { void Awake() { var ring = gameObject.AddComponent<LineRenderer>(); ring.useWorldSpace = false; ring.loop = true; ring.positionCount = 32; var points = new Vector3[32]; for (int i = 0; i < points.Length; i++) { float angle = i * Mathf.PI * 2f / points.Length; points[i] = new Vector3(Mathf.Cos(angle), Mathf.Sin(angle)) * .28f; } ring.SetPositions(points); ring.startWidth = ring.endWidth = .56f; ring.material = new Material(Shader.Find("Sprites/Default")); ring.startColor = ring.endColor = new Color(.15f, 1f, .42f) * 1.8f; } }
